  const auto& body=snake.body();

  for(int i=0;i<body.size();i++){
    Pos p=body[i].pos;
    board[p.i][p.j]=char('a'+static_cast<int>(body[i].color));
  }

  std::string s;
  for(int i=0;i<n;i++){
    s+=board[i];
    s+='\n';
  }


  s+="head: ("+std::to_string(snake.head().pos.i)+","+std::to_string(snake.head().pos.j)+")\n";

